sp_widget.client_script:
function($scope, $rootScope) {
    var chartJurosInstance = null;

    $scope.anoSelecionadoJuros = "";
    $scope.exibirGraficoJuros = false;
    $scope.tipoGraficoJuros = 'line'; // padrão linha
    $scope.dadosGraficoJuros = [];

function carregarDadosJuros() {
    var filtros = {
        ano: $scope.anoSelecionadoJuros || ""
    };

    $scope.server.get(filtros).then(function(response) {
        $scope.dadosGraficoJuros = response.data.dadosGraficoJuros || [];

        setTimeout(function () {
            inicializarGraficoJuros($scope.dadosGraficoJuros);
        }, 300); // 300ms de atraso
    });
}


    $rootScope.$on('filtroAnoIndicadoresSelecionado', function(event, ano) {
        $scope.anoSelecionadoJuros = ano;
        $scope.tipoGraficoJuros = ano ? 'bar' : 'line';
        carregarDadosJuros();
    });

    carregarDadosJuros();

    function formatarReal(valor) {
        return 'R$ ' + valor.toFixed(2)
            .replace('.', ',')
            .replace(/\B(?=(\d{3})+(?!\d))/g, '.');
    }

    function inicializarGraficoJuros(lista) {
        if (!lista || lista.length === 0) {
            if (chartJurosInstance) {
                chartJurosInstance.destroy();
                chartJurosInstance = null;
            }
            $scope.exibirGraficoJuros = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirGraficoJuros = true;
        $scope.$applyAsync();

        var labels = [];
        var jurosExternaData = [];
        var jurosInternaData = [];

        lista.forEach(function(item) {
            labels.push(item.ano);
            jurosExternaData.push(item.jurosEncargosExterna);
            jurosInternaData.push(item.jurosEncargosInterna);
        });

        var canvas = document.getElementById('graficoJuros');
        if (!canvas) {
            console.error("Elemento canvas 'graficoJuros' não encontrado.");
            return;
        }

        var ctx = canvas.getContext('2d');

        if (chartJurosInstance) {
            chartJurosInstance.destroy();
        }

        chartJurosInstance = new Chart(ctx, {
            type: $scope.tipoGraficoJuros,
            data: {
                labels: labels,
                datasets: [
                    {
                        label: 'Juros e Encargos Externa',
                        data: jurosExternaData,
                        borderColor: '#4A75B1',
                        backgroundColor: $scope.tipoGraficoJuros === 'bar' ? '#4A75B1' : 'transparent',
                        borderWidth: 2,
                        borderDash: $scope.tipoGraficoJuros === 'line' ? [6, 4] : [],
                        fill: false,
                        tension: 0.4,
                        pointRadius: 3,
                        yAxisID: 'y'
                    },
                    {
                        label: 'Juros e Encargos Interna',
                        data: jurosInternaData,
                        borderColor: '#6BB7F0',
                        backgroundColor: $scope.tipoGraficoJuros === 'bar' ? '#6BB7F0' : 'transparent',
                        borderWidth: 2,
                        borderDash: [],
                        fill: false,
                        tension: 0.4,
                        pointRadius: 3,
                        yAxisID: 'y'
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        title: {
                            display: true,
                            text: 'Ano'
                        }
                    },
                    y: {
                        beginAtZero: true,
                        title: {
                            display: true,
                            text: 'Valores (em R$)'
                        },
                        ticks: {
                            // Formata os números no eixo Y
                            callback: function(value) {
                                return formatarReal(value);
                            }
                        }
                    }
                },
                plugins: {
                    legend: {
                        position: 'top'
                    },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': ' + formatarReal(context.parsed.y);
                            }
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};
    var anoFiltroJuros = input.ano || "";

    var gr = new GlideRecord('x_sded9_portal_t_0_u_amortizacao_juros');
    if (anoFiltroJuros !== "") {
        gr.addQuery('u_ano', anoFiltroJuros);
    }
    gr.orderBy('u_ano');
    gr.query();

    var listaJuros = [];

    while (gr.next()) {
        listaJuros.push({
            ano: gr.getValue('u_ano'),
            jurosEncargosExterna: parseFloat(gr.getValue('u_juros_encargos_externa')) / 1 || 0,
            jurosEncargosInterna: parseFloat(gr.getValue('u_juros_encargos_interna')) / 1 || 0
        });
    }

    data.dadosGraficoJuros = listaJuros;
})();
